 $ago=function($ts){ if(!$ts) return '–'; $m=max(0,(int)round((time()-$ts)/60)); return date('Y-m-d H:i',$ts).' <small>('.($m<60?$m.' min':($m<2880?round($m/60,1).' h':round($m/1440).' d')).' '.t('sedan','ago').')</small>'; };
